<script setup lang="ts">
import type { AnalyticsWarning, SelectedAnalysisPoint } from '../../api/analytics'
const props=defineProps<{quality:Record<string,any>;warnings:AnalyticsWarning[];points:SelectedAnalysisPoint[]}>()
const pointName=(pointId:string)=>props.points.find(point=>point.point_id===pointId)?.point_name||pointId
</script>
